local _startupFinished = false
local function _showUpdatedHubError(message)
    warn("[VOID HUB NEW BUILD] " .. tostring(message))
    pcall(function()
        local player = game:GetService("Players").LocalPlayer
        if not player then return end
        local playerGui = player:FindFirstChildOfClass("PlayerGui")
        if not playerGui then return end
        local intro = playerGui:FindFirstChild("VoidHubV1_Intro")
        if intro then intro:Destroy() end
        local gui = playerGui:FindFirstChild("VoidHubV1")
        if gui then
            gui.Enabled = true
            local holder = gui:FindFirstChild("Holder")
            if holder then holder.Visible = true end
        end
        local existing = playerGui:FindFirstChild("VoidHubStartupError")
        if existing then existing:Destroy() end
        local statusGui = Instance.new("ScreenGui")
        statusGui.Name = "VoidHubStartupError"
        statusGui.DisplayOrder = 100005
        statusGui.ResetOnSpawn = false
        statusGui.IgnoreGuiInset = false
        statusGui.Parent = playerGui
        local textLabel = Instance.new("TextLabel")
        textLabel.Name = "NewBuildError"
        textLabel.AnchorPoint = Vector2.new(0.5, 0)
        textLabel.Position = UDim2.new(0.5, 0, 0, 10)
        textLabel.Size = UDim2.fromOffset(640, 110)
        textLabel.BackgroundColor3 = Color3.fromRGB(31, 24, 30)
        textLabel.TextColor3 = Color3.fromRGB(255, 244, 241)
        textLabel.Font = Enum.Font.GothamBold
        textLabel.TextSize = 14
        textLabel.TextWrapped = true
        textLabel.TextXAlignment = Enum.TextXAlignment.Center
        textLabel.Text = "VOID HUB NEW BUILD ERROR - No fallback used.\n"
            .. string.sub(tostring(message), 1, 390)
            .. "\nSend this error text or a screenshot to fix the exact line."
        textLabel.Parent = statusGui
        local round = Instance.new("UICorner")
        round.CornerRadius = UDim.new(0, 12)
        round.Parent = textLabel
        local close = Instance.new("TextButton")
        close.Name = "Dismiss"
        close.Position = UDim2.new(1, -32, 0, 5)
        close.Size = UDim2.fromOffset(24, 24)
        close.BackgroundTransparency = 1
        close.Text = "X"
        close.TextColor3 = Color3.fromRGB(255, 255, 255)
        close.Font = Enum.Font.GothamBold
        close.TextSize = 18
        close.Parent = textLabel
        close.Activated:Connect(function() statusGui:Destroy() end)
    end)
end

if not _compiled then
    _showUpdatedHubError("Source compilation: " .. tostring(_compileErr))
    return
end
-- Even if initialization stalls, report the condition rather than hiding
